// === Tab: mySketch ===
let N = 60; // initial number of particles
let L0 = 250; // rest length of the springs
let stiffness = 0.1; // stiffness
let dt = 0.01; // time step
let brownian_motion = 50; // random velocity magnitude
let pts = []; // array of particles
let c; // color

function setup()
{
  createCanvas(windowWidth, windowHeight);
  noStroke();
  //frameRate(50);

	noiseDetail(2,0.8); // 2 harmonics, 80% falloff

  // Create particles
  for(let i = 0; i < N; i++)
  {
    pts.push( new Particle( random(width), random(height) ) );
  }
}

function draw()
{
  background(241,240,245, 32);

	// resting length of spring force
  L0 = 200+300*noise(frameCount/100);

	// rotate drawing around center
	translate(width/2,height/2);
	rotate(frameCount/380);
	translate(-width/2,-height/2);

  // Compute velocities
  for(let i = 0; i < N; i++)
  {
    for(let j = 0; j <= i; j++)
    {
      if( i != j )
      {
        let L = mag(pts[j].x - pts[i].x, pts[j].y - pts[i].y);
        let f = stiffness*(L-L0);
        // vecteur i -> j
        let cos_ij = (pts[j].x - pts[i].x)/L;
        let sin_ij = (pts[j].y - pts[i].y)/L;
        // force of j on i
        pts[i].vx += f*cos_ij;
        pts[i].vy += f*sin_ij;
        // force of i on j
        pts[j].vx -= f*cos_ij;
        pts[j].vy -= f*sin_ij;
      }
    }
  }

  // Particles
	fill(0,0,255,60);
  for(let i = 0; i < N; i++)
  {
    pts[i].vx += brownian_motion*(2*random()-1);
    pts[i].vy += brownian_motion*(2*random()-1);
    pts[i].move(dt);
		//for(let j = 0; j < 3; j++)
			pts[i].disp();
  }

	// Connections
	if( random() > 0.98 )
	{
		let i = int(random(0,N));
		let j = int(random(0,N));
		let k = int(random(0,N));
		noFill();
		stroke(130,130,255,100);
		strokeWeight(4);
		beginShape();
			vertex(pts[i].x,pts[i].y);
			vertex(pts[j].x,pts[j].y);
			vertex(pts[k].x,pts[k].y);
		endShape();
		noStroke();
	}

	//circle(width/2,height/2,500);
}

function mousePressed()
{
	// add a random number of particles
	for(let k = int(random(1,5)); k > 0; k--)
	{
		let pos = p5.Vector.random2D().mult(height).add(width/2,height/2);
		pts.shift(); // remove first element
		pts.push( new Particle( pos.x, pos.y ) );
	}
}


class Particle
{
  constructor(x0, y0, couleur)
  {
    this.x = x0;
    this.y = y0;
    this.vx = 0;
    this.vy = 0;
  }

  move(dt)
  {
		// Euler method
    this.x += dt*this.vx;
    this.y += dt*this.vy;
		// no inertia
    this.vx = 0;
    this.vy = 0;
  }

  disp()
  {
		c = color(100+155*noise( 0.04*(this.x+this.y+frameCount) ) ,150,255);
		fill( c );
    circle(this.x, this.y, 7+35*pow(noise( 0.04*(this.x+this.y+frameCount) ),3) );

		if( random() > 0.998 )
		{
			push();
			noFill();
			stroke(c);
			strokeWeight(2);
			//line(this.x+random(-30,30),this.y+random(-30,30), this.x+random(-30,30),this.y+random(-30,30));
			circle(this.x,this.y,random(20,40));
			pop();
		}
  }
}

